class Solution {
public:
    int numSubseq(vector<int>& nums, int target) {
        const int MOD = 1000000007;
        int n = nums.size();
        sort(nums.begin(), nums.end());

        vector<int> pow2(n + 1);
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = (int)((long long)pow2[i - 1] * 2 % MOD);
        }

        long long ans = 0;
        int j = n - 1;
        for (int i = 0; i < n; i++) {
            while (j >= i && nums[i] + nums[j] > target) {
                j--;
            }
            if (j < i) break;
            ans = (ans + pow2[j - i]) % MOD;
        }
        return (int)ans;
    }
};
